// index.js or App.js
import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";

import "assets/plugins/nucleo/css/nucleo.css";
import "@fortawesome/fontawesome-free/css/all.min.css";
import "assets/scss/argon-dashboard-react.scss";

import AdminLayout from "layouts/Admin.js"; // Assuming Admin Layout handles your sidebar
import AuthRouteHandler from "src/AuthRouteHandler.js";  // Import the AuthRouteHandler

const root = ReactDOM.createRoot(document.getElementById("root"));

root.render(
  <BrowserRouter>
    <Routes>
      {/* Admin routes */}
      <Route path="/admin/*" element={<AdminLayout />} />

      {/* Authentication routes */}
      <Route path="/auth/*" element={<AuthRouteHandler />} />

      {/* Redirect to /admin/index for undefined paths */}
      <Route path="*" element={<Navigate to="/admin/index" replace />} />
    </Routes>
  </BrowserRouter>
);
